UPDATE proc_vendors AS t SET payment_terms = CASE lower(regexp_replace(btrim(t.payment_terms), '\s+', ' ', 'g')) WHEN '' THEN NULL WHEN '100% advance' THEN '100% Advance' WHEN '100% against pi' THEN '100% Against PI' WHEN '100% against dispatch' THEN '100% Against Dispatch' WHEN '100% after dispatch' THEN '100% After Dispatch' WHEN '100% after work completion' THEN '100% After Work Completion' WHEN '7 days pdc against dispatch' THEN '7 Days PDC Against Dispatch' WHEN '10 days pdc' THEN '10 Days PDC' WHEN '10 days pdc cheque' THEN '10 Days PDC Cheque' WHEN '10 days pdc against dispatch' THEN '10 Days PDC Against Dispatch' WHEN '30 days credit' THEN '30 Days Credit' WHEN '20% advance, balance 45 days credit' THEN '20% Advance, Balance 45 Days Credit' WHEN '30% advance, balance against dispatch' THEN '30% Advance, Balance Against Dispatch' WHEN '50% advance, balance against dispatch' THEN '50% Advance, Balance Against Dispatch' WHEN '50% advance, balance 30 days credit' THEN '50% Advance, Balance 30 Days Credit' WHEN '100% payment adavcne' THEN '100% Advance' WHEN '100% payment advance' THEN '100% Advance' WHEN '100% payment against dispatch' THEN '100% Against Dispatch' WHEN '10 days pdc agst dispatch' THEN '10 Days PDC Against Dispatch' WHEN '20% adv & balance 45 days credit' THEN '20% Advance, Balance 45 Days Credit' WHEN '30% adv, bal against dispatch' THEN '30% Advance, Balance Against Dispatch' WHEN '30% advance, bal against dispatch' THEN '30% Advance, Balance Against Dispatch' WHEN '30 days' THEN '30 Days Credit' WHEN '50% advance & 50% 30 days credit' THEN '50% Advance, Balance 30 Days Credit' WHEN '50% advance and balance 30 days credit' THEN '50% Advance, Balance 30 Days Credit' WHEN '50% advance & balance 50% 30 days credit' THEN '50% Advance, Balance 30 Days Credit' WHEN '50% advance & 50% against dispatch' THEN '50% Advance, Balance Against Dispatch' WHEN '50% adv, bal against dispatch' THEN '50% Advance, Balance Against Dispatch' ELSE t.payment_terms END WHERE (t.payment_terms IS DISTINCT FROM CASE lower(regexp_replace(btrim(t.payment_terms), '\s+', ' ', 'g')) WHEN '' THEN NULL WHEN '100% advance' THEN '100% Advance' WHEN '100% against pi' THEN '100% Against PI' WHEN '100% against dispatch' THEN '100% Against Dispatch' WHEN '100% after dispatch' THEN '100% After Dispatch' WHEN '100% after work completion' THEN '100% After Work Completion' WHEN '7 days pdc against dispatch' THEN '7 Days PDC Against Dispatch' WHEN '10 days pdc' THEN '10 Days PDC' WHEN '10 days pdc cheque' THEN '10 Days PDC Cheque' WHEN '10 days pdc against dispatch' THEN '10 Days PDC Against Dispatch' WHEN '30 days credit' THEN '30 Days Credit' WHEN '20% advance, balance 45 days credit' THEN '20% Advance, Balance 45 Days Credit' WHEN '30% advance, balance against dispatch' THEN '30% Advance, Balance Against Dispatch' WHEN '50% advance, balance against dispatch' THEN '50% Advance, Balance Against Dispatch' WHEN '50% advance, balance 30 days credit' THEN '50% Advance, Balance 30 Days Credit' WHEN '100% payment adavcne' THEN '100% Advance' WHEN '100% payment advance' THEN '100% Advance' WHEN '100% payment against dispatch' THEN '100% Against Dispatch' WHEN '10 days pdc agst dispatch' THEN '10 Days PDC Against Dispatch' WHEN '20% adv & balance 45 days credit' THEN '20% Advance, Balance 45 Days Credit' WHEN '30% adv, bal against dispatch' THEN '30% Advance, Balance Against Dispatch' WHEN '30% advance, bal against dispatch' THEN '30% Advance, Balance Against Dispatch' WHEN '30 days' THEN '30 Days Credit' WHEN '50% advance & 50% 30 days credit' THEN '50% Advance, Balance 30 Days Credit' WHEN '50% advance and balance 30 days credit' THEN '50% Advance, Balance 30 Days Credit' WHEN '50% advance & balance 50% 30 days credit' THEN '50% Advance, Balance 30 Days Credit' WHEN '50% advance & 50% against dispatch' THEN '50% Advance, Balance Against Dispatch' WHEN '50% adv, bal against dispatch' THEN '50% Advance, Balance Against Dispatch' ELSE t.payment_terms END);
